  `criteria_confidentiality` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criteria_integrity` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criteria_availability` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criteria_compliance` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criteria_reliability` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
