  `gov_performance_measurement` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `res_applications` tinyint(1) NOT NULL DEFAULT '1',
  `res_information` tinyint(1) NOT NULL DEFAULT '1',
  `res_infrastructure` tinyint(1) NOT NULL DEFAULT '1',
  `res_people` tinyint(1) NOT NULL DEFAULT '1',
  `maturity_intro` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
